<div class="table-responsive"><table class="table table-bordered table-striped bg-white"><thead class="table-light"><tr><th>ID</th><th>Judul</th><th>Pengarang</th><th>Penerbit</th><th>Tahun</th><th>Stok</th><th>Aksi</th></tr></thead><tbody>
